import{_ as t,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"C语言程序设计","description":"以类型、内存、指针和程序分解为主线的 C 语言阅读导引。","frontmatter":{"title":"C语言程序设计","description":"以类型、内存、指针和程序分解为主线的 C 语言阅读导引。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 编程语言与开发框架","summary":"以类型、内存、指针和程序分解为主线的 C 语言阅读导引。","status":"active","related":[{"title":"Go语言高并发与微服务实战","link":"/life/personal/books/computing/go-concurrency-microservices","kind":"书籍导读","scope":"general","audience":"general"},{"title":"深入浅出Spring Boot 2.x","link":"/life/personal/books/computing/spring-boot-2","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Redis设计与实现","link":"/life/personal/books/computing/redis-design","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Rust程序设计（第2版）","link":"/life/personal/books/computing/programming-rust","kind":"书籍导读","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Go语言高并发与微服务实战","link":"/life/personal/books/computing/go-concurrency-microservices"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Go语言高并发与微服务实战","link":"/life/personal/books/computing/go-concurrency-microservices"}},"headers":[],"relativePath":"life/personal/books/computing/c-programming.md","filePath":"life/personal/books/computing/c-programming.md"}'),n={name:"life/personal/books/computing/c-programming.md"};function i(l,e,d,s,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="c语言程序设计" tabindex="-1">C语言程序设计 <a class="header-anchor" href="#c语言程序设计" aria-label="Permalink to &quot;C语言程序设计&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 编程语言与开发框架</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书在书单中承担编程基础训练的角色。C 语言让数据表示、内存访问与控制流程直接呈现在程序中，适合希望理解程序怎样执行，或为数据结构、操作系统和系统编程打基础的读者。</p><p>学习时应同时练习“写出结果”和“解释过程”：变量何时初始化，数组能访问到哪里，指针指向的对象是否仍然有效，函数调用怎样传递数据。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>版本待确认。</strong> 同名教材较多，目前不能确定作者、版次与采用的 C 标准。以下为本站主题导读，不是原书目录；不默认它是某位作者的教材，也不把 C++ 内容混入本页。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>《C语言程序设计》作者待核对，不能默认属于谭浩强或其他某位作者。清华大学出版社可查到高禹等编著的同名第4版，高教社另有何钦铭、颜晖编著的同名教材，说明仅凭书名无法唯一识别。作者的教学经历、权威性及采用的 C 标准，应按实物 ISBN 对应的出版社记录确认。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合初学程序设计、准备继续学习数据结构或操作系统的人。已有其他语言经验的读者可以重点看对象生命周期、数组与指针；备考读者还要确认教材与考试要求采用的标准一致。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>导读主题</th><th>阅读与练习目标</th></tr></thead><tbody><tr><td>编译与程序结构</td><td>从源文件到可执行文件认识预处理、编译与链接，区分编译错误和运行错误。</td></tr><tr><td>类型与表达式</td><td>理解整数、浮点数、转换和运算优先级，检查溢出与精度问题。</td></tr><tr><td>选择与循环</td><td>练习边界条件、循环不变量和提前退出，避免只测试正常输入。</td></tr><tr><td>函数与作用域</td><td>将任务拆成职责明确的函数，区分形参、局部变量和可见范围。</td></tr><tr><td>数组与字符串</td><td>认识数组长度与字符串终止符，逐项验证下标和缓冲区容量。</td></tr><tr><td>指针与对象生命周期</td><td>区分地址、指针变量与被指向对象，分析悬空指针和重复释放。</td></tr><tr><td>结构体与数据组织</td><td>用结构体表达相关数据，比较值传递与通过指针修改对象。</td></tr><tr><td>文件与错误处理</td><td>检查打开、读取、写入和关闭的结果，让错误沿调用链被处理。</td></tr><tr><td>多文件程序</td><td>用头文件与源文件组织接口，理解声明、定义和链接可见性。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>一次正常输出，不能替代对对象边界的解释。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>练习时为每个数组写出容量、有效元素数和允许下标，为每个指针注明所指对象及有效期。这样可以把“偶尔崩溃”转化为对越界、未初始化或悬空访问的具体检查。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>本册身份未明，不能评价其例题是否陈旧或是否包含错误写法。读 C 教材尤其应核对编译模式，保留警告并配合调试器；复杂指针表达式可以先拆成多个步骤，再验证含义。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐把它当作训练精确性的基础课：学会画内存与生命周期的关系，比炫技式压缩代码更值得。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li>书名来自本次书单；原书目录、作者和 C 标准版本待版权页核对。</li><li><a href="https://en.cppreference.com/w/c" target="_blank" rel="noopener noreferrer">cppreference：C 语言参考</a>：语言规则与标准库的补充参考，不是本书目录来源。</li><li><a href="https://gcc.gnu.org/onlinedocs/" target="_blank" rel="noopener noreferrer">GCC 文档</a>：编译选项和诊断说明的补充入口。</li><li><a href="https://www.tup.com.cn/booksCenter/book_07887801.html" target="_blank" rel="noopener noreferrer">清华社：高禹等《C语言程序设计（第四版）》</a>：同名候选，ISBN 9787302494850。</li><li><a href="https://abooks.hep.com.cn/book?id=FKV23LCLR" target="_blank" rel="noopener noreferrer">高教社：何钦铭、颜晖《C语言程序设计（第4版）》</a>：另一候选；两条记录均不代表实物已确认。</li></ul>',26)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
